import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createBookmarkService } from "~/features/bookmarks/bookmark.service.server";
import { createTestDatabase } from "../helpers/database";
import { createTestAuth, testUsers } from "../helpers/auth";

describe("bookmark create and list", () => {
  let database: ReturnType<typeof createTestDatabase>;
  beforeEach(async () => { database = createTestDatabase(); await createTestAuth(database.db); });
  afterEach(() => database.cleanup());

  it("persists newest-first bookmarks and isolates owners", async () => {
    const service = createBookmarkService(database.db);
    const alice = (await database.db.query.user.findFirst({ where: (u, { eq }) => eq(u.email, testUsers.alice.email) }))!;
    const bob = (await database.db.query.user.findFirst({ where: (u, { eq }) => eq(u.email, testUsers.bob.email) }))!;
    await service.create(alice.id, { url: "https://example.com/one", title: "One", description: null, tags: [] });
    await service.create(alice.id, { url: "https://example.com/two", title: "Two", description: null, tags: [] });
    expect((await service.list(alice.id, {})).items.map((item) => item.title)).toEqual(["Two", "One"]);
    expect((await service.list(bob.id, {})).items).toEqual([]);
  });

  it("rejects a normalized duplicate per owner but allows it for another owner", async () => {
    const service = createBookmarkService(database.db);
    const [alice, bob] = await database.db.query.user.findMany();
    await service.create(alice!.id, { url: "https://EXAMPLE.com:443/a#x", title: "One", description: null, tags: [] });
    await expect(service.create(alice!.id, { url: "https://example.com/a", title: "Again", description: null, tags: [] })).rejects.toMatchObject({ code: "DUPLICATE_BOOKMARK" });
    await expect(service.create(bob!.id, { url: "https://example.com/a", title: "Bob", description: null, tags: [] })).resolves.toMatchObject({ title: "Bob" });
  });
});

/work/tests/unit/url-normalization.test..content:
import { describe, expect, it } from "vitest";
import { fallbackTitle, normalizeBookmarkUrl } from "~/features/bookmarks/url-normalization";

describe("normalizeBookmarkUrl", () => {
  it.each([
    [" example.com/path#section ", "https://example.com/path"],
    ["HTTPS://EXAMPLE.COM:443/a?b=2&a=1", "https://example.com/a?b=2&a=1"],
    ["http://example.com:80", "http://example.com/"],
    ["https://bücher.example/", "https://xn--bcher-kva.example/"],
  ])("normalizes %s", (input, expected) => expect(normalizeBookmarkUrl(input)).toBe(expected));

  it("keeps HTTP and HTTPS distinct", () => {
    expect(normalizeBookmarkUrl("http://example.com")).not.toBe(normalizeBookmarkUrl("https://example.com"));
  });

  it.each(["file:///tmp/x", "javascript:alert(1)", "https://u:p@example.com", "localhost", "not a url"])(
    "rejects %s",
    (input) => expect(() => normalizeBookmarkUrl(input)).toThrow(),
  );

  it("enforces the URL limit", () => expect(() => normalizeBookmarkUrl(`https://example.com/${"x".repeat(2050)}`)).toThrow());
  it("creates a readable fallback", () => expect(fallbackTitle("https://example.com/good-article")).toBe("example.com — good article"));
});

/work/tests/security/fetch-page.test.ts.content:
import { createServer } from "node:http";
import { afterEach, describe, expect, it } from "vitest";
import { fetchPage } from "~/services/metadata/fetch-page.server";

describe("bounded metadata fetch", () => {
  const servers: ReturnType<typeof createServer>[] = [];
  afterEach(() => { for (const server of servers.splice(0)) server.close(); });

  it("retrieves bounded HTML through an injected approved resolver", async () => {
    const server = createServer((_request, response) => response.end("<title>Fixture</title>"));
    servers.push(server);
    await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
    const address = server.address();
    if (!address || typeof address === "string") throw new Error("fixture did not start");
    const result = await fetchPage(new URL(`http://fixture.test:${address.port}`), {
      allowTestPorts: true,
      resolver: async () => [{ address: "127.0.0.1", family: 4 }],
      allowAddress: () => true,
    });
    expect(result.body.toString()).toContain("Fixture");
  });

  it("rejects non-HTML and oversized streams", async () => {
    const server = createServer((_request, response) => {
      response.setHeader("content-type", "application/octet-stream");
      response.end("binary");
    });
    servers.push(server);
    await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
    const address = server.address();
    if (!address || typeof address === "string") throw new Error("fixture did not start");
    await expect(fetchPage(new URL(`http://fixture.test:${address.port}`), {
      allowTestPorts: true,
      resolver: async () => [{ address: "127.0.0.1", family: 4 }],
      allowAddress: () => true,
    })).rejects.toThrow("non_html");
  });
});

