import { and, desc, eq } from "drizzle-orm";
import type { AppDatabase } from "~/db/client.server";
import { bookmark } from "~/db/schema";

export type BookmarkRecord = typeof bookmark.$inferSelect;
export type BookmarkView = {
  id: string;
  url: string;
  title: string;
  description: string | null;
  tags: { id: string; name: string }[];
  createdAt: string;
  updatedAt: string;
};

export function toBookmarkView(row: BookmarkRecord, tags: BookmarkView["tags"] = []): BookmarkView {
  return {
    id: row.id,
    url: row.url,
    title: row.title,
    description: row.description,
    tags,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

export function createBookmarkRepository(db: AppDatabase) {
  return {
    findByNormalizedUrl(ownerId: string, normalizedUrl: string) {
      return db.select().from(bookmark).where(and(eq(bookmark.ownerId, ownerId), eq(bookmark.normalizedUrl, normalizedUrl))).limit(1).get();
    },
    findById(ownerId: string, id: string) {
      return db.select().from(bookmark).where(and(eq(bookmark.ownerId, ownerId), eq(bookmark.id, id))).limit(1).get();
    },
    insert(values: typeof bookmark.$inferInsert) {
      return db.insert(bookmark).values(values).returning().get();
    },
    list(ownerId: string, limit = 50) {
      return db.select().from(bookmark).where(eq(bookmark.ownerId, ownerId)).orderBy(desc(bookmark.createdAt), desc(bookmark.id)).limit(limit).all();
    },
  };
}
import { useEffect, useRef, useState } from "react";
import { StatusRegion } from "./ui/status-region";
import { TagInput } from "./tag-input";

type Preview = {
  requestId: string;
  url: string;
  title: string;
  description: string | null;
  status: "retrieved" | "fallback";
  warningCode: string | null;
  duplicate: { id: string; title: string } | null;
};

export function BookmarkEditor({ onSaved, tagSuggestions = [] }: { onSaved: () => void | Promise<void>; tagSuggestions?: string[] }) {
  const [url, setUrl] = useState("");
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [tags, setTags] = useState<string[]>([]);
  const [status, setStatus] = useState("");
  const [pendingPreview, setPendingPreview] = useState(false);
  const [pendingSave, setPendingSave] = useState(false);
  const [duplicate, setDuplicate] = useState<Preview["duplicate"]>(null);
  const titleDirty = useRef(false);
  const descriptionDirty = useRef(false);
  const latestRequest = useRef("");
  const urlRef = useRef<HTMLInputElement>(null);

  async function retrieveDetails() {
    if (!url.trim() || pendingPreview) return;
    const requestId = crypto.randomUUID();
    latestRequest.current = requestId;
    setPendingPreview(true);
    setStatus("Retrieving page details…");
    setDuplicate(null);
    try {
      const response = await fetch("/api/metadata/preview", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ url, requestId }),
      });
      const result = await response.json() as Preview & { message?: string };
      if (latestRequest.current !== requestId) return;
      if (!response.ok) {
        setStatus(result.message ?? "Enter a valid web address.");
        urlRef.current?.focus();
        return;
      }
      setUrl(result.url);
      if (!titleDirty.current) setTitle(result.title);
      if (!descriptionDirty.current) setDescription(result.description ?? "");
      setDuplicate(result.duplicate);
      setStatus(result.duplicate
        ? "This page is already in your library."
        : result.status === "retrieved"
          ? "Page details added. You can edit them before saving."
          : "Page details weren’t available, so we made a title from the address. You can edit it.");
    } catch {
      setStatus("We couldn’t retrieve page details. Please try again.");
    } finally {
      if (latestRequest.current === requestId) setPendingPreview(false);
    }
  }

  useEffect(() => {
    if (!url.trim() || titleDirty.current) return;
    const timer = window.setTimeout(() => void retrieveDetails(), 700);
    return () => window.clearTimeout(timer);
    // URL changes intentionally schedule a fresh preview.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [url]);

  return (
    <section className="capture-card" aria-labelledby="save-heading">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Quick save</p>
          <h2 id="save-heading">What caught your eye?</h2>
        </div>
        <span className="capture-mark" aria-hidden="true">＋</span>
      </div>
      <form onSubmit={async (event) => {
        event.preventDefault();
        if (!title.trim()) {
          await retrieveDetails();
          return;
        }
        setPendingSave(true);
        setStatus("Saving bookmark…");
        const response = await fetch("/api/bookmarks", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ url, title, description: description || null, tags }),
        });
        const result = await response.json().catch(() => ({})) as { message?: string; existingBookmark?: Preview["duplicate"] };
        setPendingSave(false);
        if (!response.ok) {
          setDuplicate(result.existingBookmark ?? null);
          setStatus(result.message ?? "The bookmark could not be saved.");
          return;
        }
        setUrl("");
        setTitle("");
        setDescription("");
        setTags([]);
        titleDirty.current = false;
        descriptionDirty.current = false;
        setDuplicate(null);
        setStatus("Bookmark saved.");
        await onSaved();
        urlRef.current?.focus();
      }}>
        <div className="url-row">
          <label className="field grow" htmlFor="bookmark-url">
            <span>Web address</span>
            <input ref={urlRef} id="bookmark-url" type="text" inputMode="url" maxLength={2048} placeholder="Paste a link — example.com/article" value={url} onChange={(event) => {
              latestRequest.current = "";
              setUrl(event.target.value);
              setDuplicate(null);
              if (!event.target.value) {
                setTitle("");
                setDescription("");
                titleDirty.current = false;
                descriptionDirty.current = false;
              }
            }} required />
          </label>
          <button className="button button-secondary details-button" type="button" disabled={!url.trim() || pendingPreview} onClick={() => void retrieveDetails()}>
            {pendingPreview ? "Getting details…" : "Get page details"}
          </button>
        </div>
        <div className="details-grid">
          <label className="field">
            <span>Title</span>
            <input aria-label="Title" maxLength={300} value={title} onChange={(event) => { titleDirty.current = true; setTitle(event.target.value); }} required />
          </label>
          <label className="field">
            <span>Description <small>Optional</small></span>
            <textarea aria-label="Description" maxLength={1000} rows={3} value={description} onChange={(event) => { descriptionDirty.current = true; setDescription(event.target.value); }} />
          </label>
        </div>
        <TagInput value={tags} onChange={setTags} suggestions={tagSuggestions} />
        <div className="capture-footer">
          <StatusRegion message={status} />
          {duplicate ? <a className="duplicate-link" href={`#bookmark-${duplicate.id}`}>View “{duplicate.title}”</a> : null}
          <button className="button button-primary" type="submit" disabled={pendingSave || pendingPreview || !url.trim() || !title.trim() || Boolean(duplicate)}>
            {pendingSave ? "Saving…" : "Save bookmark"}
          </button>
        </div>
      </form>
    </section>
  );
}
import { useState } from "react";

export function TagInput({ value, onChange, suggestions = [] }: {
  value: string[];
  onChange: (tags: string[]) => void;
  suggestions?: string[];
}) {
  const [draft, setDraft] = useState("");

  function addTag(raw: string) {
    const trimmed = raw.normalize("NFKC").replace(/\s+/g, " ").trim();
    if (!trimmed || trimmed.length > 50 || value.length >= 20) return;
    const suggestion = suggestions.find((item) => item.toLocaleLowerCase() === trimmed.toLocaleLowerCase());
    const display = suggestion ?? trimmed;
    if (!value.some((item) => item.toLocaleLowerCase() === display.toLocaleLowerCase())) onChange([...value, display]);
    setDraft("");
  }

  return (
    <div className="tag-field">
      <label htmlFor="bookmark-tags">Tags <small>Optional</small></label>
      <div className="tag-input-wrap">
        {value.map((tag) => (
          <span className="tag-chip" key={tag}>{tag}<button type="button" aria-label={`Remove ${tag}`} onClick={() => onChange(value.filter((item) => item !== tag))}>×</button></span>
        ))}
        <input id="bookmark-tags" aria-label="Tags" list="tag-suggestions" maxLength={50} value={draft} placeholder={value.length ? "Add another" : "Add tags"} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === ",") { event.preventDefault(); addTag(draft); }
          if (event.key === "Backspace" && !draft && value.length) onChange(value.slice(0, -1));
        }} onBlur={() => addTag(draft)} />
        <datalist id="tag-suggestions">{suggestions.map((tag) => <option key={tag} value={tag} />)}</datalist>
      </div>
      <span className="field-help">Press Enter to add · {value.length}/20</span>
    </div>
  );
}
import type { BookmarkView } from "~/features/bookmarks/bookmark.repository.server";

function hostname(url: string) {
  try { return new URL(url).hostname.replace(/^www\./, ""); }
  catch { return url; }
}

export function BookmarkCard({ bookmark }: { bookmark: BookmarkView }) {
  return (
    <article className="bookmark-card" id={`bookmark-${bookmark.id}`}>
      <div className="site-badge" aria-hidden="true">{hostname(bookmark.url).charAt(0).toUpperCase()}</div>
      <div className="bookmark-copy">
        <p className="bookmark-host">{hostname(bookmark.url)}</p>
        <h3><a href={bookmark.url} target="_blank" rel="noopener noreferrer">{bookmark.title}<span className="external" aria-hidden="true">↗</span></a></h3>
        {bookmark.description ? <p className="bookmark-description">{bookmark.description}</p> : null}
        {bookmark.tags.length ? <div className="bookmark-tags">{bookmark.tags.map((tag) => <span className="tag-chip static" key={tag.id}>{tag.name}</span>)}</div> : null}
        <footer>
          <time dateTime={bookmark.createdAt}>Saved {new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date(bookmark.createdAt))}</time>
        </footer>
      </div>
    </article>
  );
}
