import { requireResourceUser } from "~/auth/require-user.server";
import { db } from "~/db/client.server";
import { metadataPreviewInputSchema } from "~/features/bookmarks/bookmark.validation";
import { validationProblem, problem } from "~/lib/http-problem.server";
import { createMetadataService } from "~/services/metadata/metadata.service.server";

const attempts = new Map<string, number[]>();

export async function action({ request }: ActionFunctionArgs) {
  const user = await requireResourceUser(request);
  const now = Date.now();
  const recent = (attempts.get(user.id) ?? []).filter((time) => now - time < 60_000);
  if (recent.length >= 20) return problem(429, "RATE_LIMITED", "Please wait before retrieving more page details.");
  recent.push(now);
  attempts.set(user.id, recent);
  const parsed = metadataPreviewInputSchema.safeParse(await request.json().catch(() => null));
  if (!parsed.success) return validationProblem(parsed.error);
  try {
    return Response.json(await createMetadataService(db).preview(user.id, parsed.data.url, parsed.data.requestId));
  } catch (error) {
    return problem(422, "VALIDATION_ERROR", error instanceof Error ? error.message : "Enter a valid web address.");
  }
}
import type { AppDatabase } from "~/db/client.server";
import { createBookmarkService } from "~/features/bookmarks/bookmark.service.server";
import { fallbackTitle, normalizeBookmarkUrl } from "~/features/bookmarks/url-normalization";
import { fetchPage, type FetchPageOptions } from "./fetch-page.server";
import { parsePageMetadata } from "./metadata-parser.server";

export type MetadataWarning = "unreachable" | "blocked" | "timeout" | "non_html" | "missing_title";

function warningFrom(error: unknown): MetadataWarning {
  const message = error instanceof Error ? error.message : "unreachable";
  return (["blocked", "timeout", "non_html", "missing_title"] as const).includes(message as any)
    ? (message as MetadataWarning)
    : "unreachable";
}

export function createMetadataService(db: AppDatabase, fetchOptions: FetchPageOptions = {}) {
  const bookmarks = createBookmarkService(db);
  return {
    async preview(ownerId: string, inputUrl: string, requestId: string) {
      const url = normalizeBookmarkUrl(inputUrl);
      const duplicate = bookmarks.findDuplicate(ownerId, url);
      if (duplicate) {
        return { requestId, url, title: duplicate.title, description: null, status: "fallback" as const, warningCode: null, duplicate };
      }
      try {
        const fetched = await fetchPage(new URL(url), fetchOptions);
        const metadata = parsePageMetadata(fetched.body);
        if (!metadata.title) throw new Error("missing_title");
        return { requestId, url, title: metadata.title, description: metadata.description, status: "retrieved" as const, warningCode: null, duplicate: null };
      } catch (error) {
        return { requestId, url, title: fallbackTitle(url), description: null, status: "fallback" as const, warningCode: warningFrom(error), duplicate: null };
      }
    },
  };
}
type LogLevel = "info" | "warn" | "error";
const sensitive = /password|secret|token|authorization|cookie/i;

function sanitize(fields: Record<string, unknown>) {
  return Object.fromEntries(Object.entries(fields).map(([key, value]) => {
    if (sensitive.test(key)) return [key, "[redacted]"];
    if (key.toLowerCase().includes("url") && typeof value === "string") {
      try {
        const url = new URL(value);
        return [key, `${url.protocol}//${url.host}${url.pathname}`];
      } catch {
        return [key, "[invalid-url]"];
      }
    }
    return [key, value];
  }));
}

export function log(level: LogLevel, event: string, fields: Record<string, unknown> = {}) {
  const entry = JSON.stringify({ level, event, ...sanitize(fields) });
  if (level === "error") console.error(entry);
  else if (level === "warn") console.warn(entry);
  else console.info(entry);
}
