import http from "node:http";
import https from "node:https";
import type { LookupFunction } from "node:net";
import {
  isPublicAddress,
  normalizeAddress,
  resolvePublicAddresses,
  type AddressResolver,
  type ResolvedAddress,
} from "./address-policy.server";

const MAX_BODY = 512 * 1024;
const REDIRECTS = new Set([301, 302, 303, 307, 308]);

export type FetchPageOptions = {
  resolver?: AddressResolver;
  allowAddress?: (address: string) => boolean;
  allowTestPorts?: boolean;
  deadlineMs?: number;
};

export type FetchedPage = { body: Buffer; contentType: string; finalUrl: string };

function pinnedLookup(addresses: ResolvedAddress[]): LookupFunction {
  return ((_hostname: string, options: any, callback: any) => {
    if (typeof options === "object" && options.all) {
      callback(null, addresses);
      return;
    }
    const first = addresses[0];
    callback(null, first?.address, first?.family);
  }) as LookupFunction;
}

function resolveLocation(current: URL, location: string) {
  try { return new URL(location, current); }
  catch { throw new Error("unreachable"); }
}

export async function fetchPage(url: URL, options: FetchPageOptions = {}): Promise<FetchedPage> {
  const started = Date.now();
  const visited = new Set<string>();
  const deadlineMs = options.deadlineMs ?? 2500;

  async function hop(current: URL, redirectCount: number): Promise<FetchedPage> {
    if (current.protocol !== "http:" && current.protocol !== "https:") throw new Error("blocked");
    if (current.username || current.password) throw new Error("blocked");
    const port = current.port || (current.protocol === "https:" ? "443" : "80");
    if (!options.allowTestPorts && port !== "80" && port !== "443") throw new Error("blocked");
    if (visited.has(current.toString()) || redirectCount > 3) throw new Error("unreachable");
    visited.add(current.toString());

    const rawAddresses = options.resolver
      ? await options.resolver(current.hostname.replace(/^\[|\]$/g, ""))
      : await resolvePublicAddresses(current.hostname);
    const allow = options.allowAddress ?? isPublicAddress;
    if (!rawAddresses.length || rawAddresses.some(({ address }) => !allow(address))) throw new Error("blocked");
    const addresses = rawAddresses.map((entry) => ({ ...entry, address: normalizeAddress(entry.address) }));
    const remaining = deadlineMs - (Date.now() - started);
    if (remaining <= 0) throw new Error("timeout");

    return new Promise<FetchedPage>((resolve, reject) => {
      const transport = current.protocol === "https:" ? https : http;
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(new Error("timeout")), remaining);
      timer.unref();
      const request = transport.request(current, {
        method: "GET",
        agent: false,
        lookup: pinnedLookup(addresses),
        signal: controller.signal,
        maxHeaderSize: 16 * 1024,
        headers: {
          accept: "text/html,application/xhtml+xml;q=0.9",
          "accept-encoding": "identity",
          "user-agent": "KeepsakeMetadata/1.0",
        },
      }, (response) => {
        if (response.rawHeaders.length / 2 > 100) {
          response.destroy();
          reject(new Error("unreachable"));
          return;
        }
        const status = response.statusCode ?? 0;
        const location = response.headers.location;
        if (REDIRECTS.has(status) && location) {
          response.resume();
          const next = resolveLocation(current, location);
          if (current.protocol === "https:" && next.protocol === "http:") {
            clearTimeout(timer);
            reject(new Error("blocked"));
            return;
          }
          clearTimeout(timer);
          void hop(next, redirectCount + 1).then(resolve, reject);
          return;
        }
        if (status < 200 || status >= 300) {
          response.resume();
          clearTimeout(timer);
          reject(new Error("unreachable"));
          return;
        }
        const contentType = String(response.headers["content-type"] ?? "").toLowerCase();
        if (!contentType.includes("text/html") && !contentType.includes("application/xhtml+xml")) {
          response.resume();
          clearTimeout(timer);
          reject(new Error("non_html"));
          return;
        }
        const encoding = String(response.headers["content-encoding"] ?? "identity").toLowerCase();
        if (encoding !== "identity") {
          response.resume();
          clearTimeout(timer);
          reject(new Error("non_html"));
          return;
        }
        const declaredLength = Number(response.headers["content-length"] ?? 0);
        if (declaredLength > MAX_BODY) {
          response.destroy();
          clearTimeout(timer);
          reject(new Error("unreachable"));
          return;
        }
        const chunks: Buffer[] = [];
        let size = 0;
        response.on("data", (chunk: Buffer) => {
          size += chunk.length;
          if (size > MAX_BODY) response.destroy(new Error("unreachable"));
          else chunks.push(Buffer.from(chunk));
        });
        response.on("end", () => {
          clearTimeout(timer);
          resolve({ body: Buffer.concat(chunks), contentType, finalUrl: current.toString() });
        });
        response.on("error", (error) => {
          clearTimeout(timer);
          reject(error.message === "unreachable" ? error : new Error("unreachable"));
        });
      });

      request.setTimeout(750, () => request.destroy(new Error("timeout")));
      request.on("socket", (socket) => {
        const verifyPeer = () => {
          const peer = normalizeAddress(socket.remoteAddress ?? "");
          if (!addresses.some(({ address }) => normalizeAddress(address) === peer)) request.destroy(new Error("blocked"));
        };
        socket.once(current.protocol === "https:" ? "secureConnect" : "connect", verifyPeer);
      });
      request.on("error", (error) => {
        clearTimeout(timer);
        if (controller.signal.aborted) reject(new Error("timeout"));
        else if (["blocked", "timeout", "non_html", "unreachable"].includes(error.message)) reject(error);
        else reject(new Error("unreachable"));
      });
      request.end();
    });
  }

  return hop(url, 0);
}
import { createServer } from "node:http";
import { afterEach, describe, expect, it } from "vitest";
import { fetchPage } from "~/services/metadata/fetch-page.server";

describe("bounded metadata fetch", () => {
  const servers: ReturnType<typeof createServer>[] = [];
  afterEach(() => { for (const server of servers.splice(0)) server.close(); });

  it("retrieves bounded HTML through an injected approved resolver", async () => {
    const server = createServer((_request, response) => {
      response.setHeader("content-type", "text/html; charset=utf-8");
      response.end("<title>Fixture</title>");
    });
    servers.push(server);
    await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
    const address = server.address();
    if (!address || typeof address === "string") throw new Error("fixture did not start");
    const result = await fetchPage(new URL(`http://fixture.test:${address.port}`), {
      allowTestPorts: true,
      resolver: async () => [{ address: "127.0.0.1", family: 4 }],
      allowAddress: () => true,
    });
    expect(result.body.toString()).toContain("Fixture");
  });

  it("rejects non-HTML and oversized streams", async () => {
    const server = createServer((_request, response) => {
      response.setHeader("content-type", "application/octet-stream");
      response.end("binary");
    });
    servers.push(server);
    await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
    const address = server.address();
    if (!address || typeof address === "string") throw new Error("fixture did not start");
    await expect(fetchPage(new URL(`http://fixture.test:${address.port}`), {
      allowTestPorts: true,
      resolver: async () => [{ address: "127.0.0.1", family: 4 }],
      allowAddress: () => true,
    })).rejects.toThrow("non_html");
  });
});
import { describe, expect, it } from "vitest";
import { isPublicAddress, resolvePublicAddresses } from "~/services/metadata/address-policy.server";

describe("metadata address policy", () => {
  it.each([
    "127.0.0.1", "127.1.2.3", "0.0.0.0", "10.0.0.1", "100.64.0.1", "169.254.169.254",
    "172.16.0.1", "192.168.1.1", "224.0.0.1", "192.0.2.1", "198.51.100.2", "203.0.113.3",
    "::1", "::", "fc00::1", "fe80::1", "::ffff:127.0.0.1", "64:ff9b::a00:1", "2001:db8::1",
  ])("blocks %s", (address) => expect(isPublicAddress(address)).toBe(false));

  it.each(["8.8.8.8", "1.1.1.1", "2606:4700:4700::1111"])("allows %s", (address) => expect(isPublicAddress(address)).toBe(true));

  it("rejects mixed public and private DNS answers", async () => {
    await expect(resolvePublicAddresses("example.com", async () => [
      { address: "93.184.216.34", family: 4 as const },
      { address: "127.0.0.1", family: 4 as const },
    ])).rejects.toThrow("blocked");
  });
});
import { useState } from "react";
import { redirect, useNavigate } from "react-router";
import type { Route } from "./+types/_auth.login";
import { getSession } from "~/auth/require-user.server";
import { config } from "~/config.server";
import { authClient } from "~/lib/auth-client";

export async function loader({ request }: Route.LoaderArgs) {
  const session = await getSession(request);
  if (session) throw redirect("/");
  return { reviewMode: config.reviewMode };
}

export default function Login({ loaderData }: Route.ComponentProps) {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");

  return (
    <main className="login-page" data-harness-ready="true">
      <section className="login-intro" aria-labelledby="login-title">
        <a className="brand" href="/" aria-label="Keepsake home">
          <span className="brand-mark" aria-hidden="true">K</span>
          <span>Keepsake</span>
        </a>
        <div>
          <p className="eyebrow">Your corner of the web</p>
          <h1 id="login-title">Keep the good parts.</h1>
          <p className="login-lede">Save the pages worth returning to, then find them again without the clutter.</p>
        </div>
        <div className="login-feature">
          <span aria-hidden="true">↗</span>
          <p><strong>Paste once.</strong><br />We’ll bring back the title and description.</p>
        </div>
      </section>

      <section className="login-card" aria-label="Sign in">
        <p className="eyebrow">Welcome back</p>
        <h2>Sign in to your library</h2>
        <form onSubmit={async (event) => {
          event.preventDefault();
          setError("");
          setPending(true);
          const result = await authClient.signIn.email({ email, password });
          setPending(false);
          if (result.error) {
            setError("That email and password didn’t match. Please try again.");
            return;
          }
          await navigate("/");
        }}>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" autoComplete="email" required value={email} onChange={(event) => setEmail(event.target.value)} />
          <label htmlFor="password">Password</label>
          <input id="password" name="password" type="password" autoComplete="current-password" required minLength={10} value={password} onChange={(event) => setPassword(event.target.value)} />
          {error ? <p className="form-error" role="alert">{error}</p> : null}
          <button className="button button-primary button-wide" disabled={pending} type="submit">{pending ? "Signing in…" : "Sign in"}</button>
        </form>
        {loaderData.reviewMode ? (
          <aside className="review-hint">
            <strong>Review account</strong>
            <span>alice@example.test</span>
            <span>Bookmarks-Alice-2026!</span>
          </aside>
        ) : null}
      </section>
    </main>
  );
}

