  const bobContext = await browser.newContext();
  const alice = await signIn(aliceContext, "alice@example.test", "Bookmarks-Alice-2026!");
  const bob = await signIn(bobContext, "bob@example.test", "Bookmarks-Bob-2026!");
  const url = `https://example.invalid/private-${Date.now()}`;
  const created = await alice.request.post("/api/bookmarks", { data: { url, title: "Alice private", description: null, tags: ["Secret"] } });
  expect(created.status()).toBe(201);
  const bookmark = await created.json() as { id: string };
  const bobList = await bob.request.get("/api/bookmarks?query=Alice%20private");
  expect((await bobList.json()).items).toHaveLength(0);
  expect((await bob.request.patch(`/api/bookmarks/${bookmark.id}`, { data: { url, title: "Taken", description: null, tags: [] } })).status()).toBe(404);
  expect((await bob.request.delete(`/api/bookmarks/${bookmark.id}`)).status()).toBe(404);
  expect((await alice.request.get("/api/bookmarks?query=Alice%20private")).status()).toBe(200);
  expect((await request.get("/api/bookmarks")).status()).toBe(401);
  await aliceContext.close();
  await bobContext.close();
});

