const current = await tools.exec_command({cmd:"cat specs/001-bookmark-manager/tasks.md","workdir":"/work","yield_time_ms":10000,"max_output_tokens":50000});
const lines = current.output.split("\n").filter(line => /^- \[ \] T\d{3}/.test(line));
let patch = "*** Begin Patch\n*** Update File: /work/specs/001-bookmark-manager/tasks.md\n";
for (const line of lines) patch += `@@\n-${line}\n+${line.replace("- [ ]", "- [X]")}\n`;
patch += "*** End Patch";
const result = await tools.apply_patch(patch);
text(JSON.stringify({updated: lines.length, result}));
